[latex]\begin{aligned}
e^{j 5 t} &=\cos 5 t+i \sin 5 t \\
L\left\{e^{(i 5 f)}\right\}&=\frac{s}{s^{2}+25}+\frac{5 i}{s^{2}+25} \\
&=\frac{s+5 i}{s^{2}+25} 2 e^{-x^{2}}
\end{aligned}[/latex]

